using LeetCode.Common;

namespace LeetCode.DP._3920._Maximize_Fixed_Points_After_Deletions;

/// <summary>
/// https://leetcode.com/problems/maximize-fixed-points-after-deletions
/// </summary>
public class Solution
{
  public int MaxFixedPoints(int[] nums)
  {
    int n = nums.Length;
    List<(int offset, int x)> candidates = [];
    for (int i = 0; i < n; i++)
    {
      int x = nums[i];
      int offset = i - x;
      if (offset >= 0)
      {
        candidates.Add((offset, x));
      }
    }
    candidates.Sort();

    List<int> seq = [];
    foreach (var item in candidates)
    {
      int pos = seq.BinarySearch(item.x);
      if (pos < 0)
      {
        pos = ~pos;
      }
      if (pos == seq.Count)
      {
        seq.Add(item.x);
      }
      else
      {
        seq[pos] = item.x;
      }
    }
    return seq.Count;
  }
}

